# category, title, focus, action, evidence
TOPICS = [
    ("Credit cards", "Unrecognized credit-card transaction", "A transaction appears on the card statement or alert that the cardholder does not recognize.", "Lock or temporarily block the card in the issuer's official app if available, call the published number, and report the transaction promptly. Ask the issuer to register a dispute, block further use, explain liability review, and provide a case reference. Do not wait for a merchant response before reporting possible fraud.", "Record the transaction date, amount, currency, merchant descriptor, alert time, last four card digits only, and dispute reference. Preserve the statement and screenshots after hiding full card details. Never share CVV, PIN, OTP, password, or full card number."),
    ("Credit cards", "Card-not-present online payment fraud", "An online, mail-order, or app transaction was not authorized by the cardholder.", "Use the bank's official channel to block the card and raise an unauthorized-transaction complaint immediately. Ask whether recurring mandates or stored-card tokens must also be disabled, request a replacement card, and follow the bank's written dispute instructions. Change compromised merchant passwords from a trusted device.", "Keep the transaction alert, merchant name, timestamp, amount, device or email notices, and complaint number. Do not click refund links sent by unknown callers or provide remote screen access."),
    ("Credit cards", "Card stolen, misplaced, or retained", "The physical card is missing, stolen, or retained by an ATM or payment terminal.", "Freeze or hot-list the card through the bank's official app or published phone line; request a replacement and confirm the old card is blocked. Review recent transactions and dispute any unfamiliar activity. If stolen, consider a police report when requested by the issuer or appropriate for the circumstances.", "Note when and where the card went missing, last four digits, block time, replacement request, and reference number. Never disclose the PIN to staff or callers."),
    ("Credit cards", "Duplicate or repeated card charge", "The same purchase appears more than once, or an authorization and final charge both appear.", "Check whether entries are pending authorizations or posted transactions and compare merchant receipts. Ask the merchant to reverse a duplicate where appropriate, while also opening an issuer dispute within the issuer's stated process. Track each transaction reference separately.", "Collect date, amount, merchant, receipt, order ID, and whether entries are pending or posted. Do not assume a pending authorization will reverse on a particular date; ask the issuer for its applicable timeline."),
    ("Credit cards", "Refund missing after cancellation", "A merchant confirms a refund, but the credit-card balance or statement does not show it.", "Ask the merchant for the refund reference, amount, date, and original transaction mapping. Contact the issuer with those details and ask whether the refund is pending, posted to a later statement, or requires a dispute. Continue paying at least the undisputed amount due while the matter is reviewed, and ask the issuer how disputed sums affect the account.", "Keep cancellation confirmation, merchant refund proof, original transaction, statement, and issuer case number. Do not pay a third party to release a refund."),
    ("Credit cards", "Statement amount or billed total looks wrong", "The total due, fee, tax, interest, or transaction entry differs from the cardholder's records.", "Reconcile opening balance, posted purchases, payments, reversals, fees, taxes, and credits line by line. Download the detailed statement and raise a written query with the exact entries. Ask the issuer to identify the calculation basis and due date while the review is open.", "Save statements, receipts, payment confirmation IDs, and any prior query. Distinguish statement balance, total amount due, and minimum amount due; paying only the minimum may leave interest-bearing balances."),
    ("Credit cards", "Interest or finance charge dispute", "Interest has been charged after a payment, refund, or balance transfer.", "Review the statement cycle, payment posting date, outstanding balances, grace-period terms, cash advances, EMI balances, and fee reversals. Ask the issuer for a transaction-level calculation and the applicable card agreement terms. Submit a written billing complaint if the calculation still does not match.", "Retain previous and current statements, payment timestamps, receipts, and card terms. Interest rules vary by issuer and transaction type; do not assume a purchase refund immediately removes all accrued interest."),
    ("Credit cards", "Minimum due paid but balance keeps growing", "The cardholder pays the minimum amount but sees the balance or interest rise.", "Review the statement's total due, minimum due, interest, fees, new spending, EMI amounts, and payment credits. If affordable, stop new card spending and plan repayment above the minimum; contact the issuer to discuss approved repayment options before missing a due date. Do not accept an informal settlement promise by phone alone.", "Build a dated balance worksheet from statements and payment proofs. The minimum due is not the same as full repayment and can extend debt repayment; verify the account-specific rate and charges."),
    ("Credit cards", "Card payment not reflected", "A payment was made, but the card account still shows the amount as unpaid or overdue.", "Check the payment channel, transaction status, beneficiary, date, and card account number entered. Save the bank debit proof and payment reference; contact both the payment provider and card issuer through official channels. Ask for the posting date and whether a late fee can be reviewed if payment was timely but delayed in settlement.", "Keep the debit SMS, bank statement, payment confirmation, and card statement. Avoid paying again until the first transfer status is understood, unless the issuer advises how to avoid delinquency."),
    ("Credit cards", "Credit limit reduced or card declined", "A purchase is declined or the available limit changes unexpectedly.", "Check card status, available limit, unbilled EMI holds, pending authorizations, channel or international-use settings, and issuer notifications. Contact the issuer to identify the decline reason and ask whether a security review, limit change, or merchant restriction applies. Never repeatedly retry a suspicious merchant transaction.", "Capture merchant, time, amount, decline code, and issuer alert. The issuer determines limits and authorization decisions under its card terms."),
    ("Credit cards", "Credit-card EMI or conversion dispute", "A purchase was converted to EMI, or an EMI amount, tenure, fee, or interest seems incorrect.", "Compare the original purchase and conversion consent with the statement's EMI principal, rate, processing fee, taxes, tenure, and outstanding balance. Ask the issuer for the conversion confirmation and amortization details. Dispute a conversion you did not authorize and request that future charges be reviewed under the written terms.", "Keep the purchase receipt, consent screen or message, EMI schedule, and statement. Do not rely on a merchant's verbal EMI quote as the final issuer offer."),
    ("Credit cards", "Recurring subscription or card mandate charge", "A subscription renews after cancellation or an unexpected recurring card payment occurs.", "Cancel with the merchant using its official account controls and save confirmation. Ask the issuer whether the mandate or token can be stopped and dispute a charge if the cancellation or authorization facts support it. For suspected account compromise, block and replace the card and review other subscriptions.", "Record the mandate descriptor, merchant, cancellation date, terms, and transaction IDs. Blocking a card may not cancel the underlying subscription contract."),
    ("Credit cards", "Credit-card complaint escalation", "A card complaint remains unresolved, has been rejected, or lacks a clear written response.", "First submit the complaint to the issuer's grievance channel and retain the acknowledgement or docket number. Escalate to the issuer's designated grievance officer if the first response is unsatisfactory. Under the RBI Integrated Ombudsman Scheme, a complaint may generally be taken to RBI after the regulated entity has rejected it, given an unsatisfactory response, or not responded within 30 days, subject to scheme eligibility and exclusions.", "Prepare a dated chronology, statement, correspondence, issuer response, and requested resolution. Lodge only through RBI's official CMS and review the current scheme rules before filing."),
    ("Debit cards", "Unrecognized debit-card transaction", "Money was debited from a linked bank account through a card transaction the customer does not recognize.", "Immediately block the debit card using the bank's official app, phone number, or branch; report the transaction and request a complaint reference. Ask the bank to protect the account, investigate the channel used, and explain its unauthorised-transaction process. Notify the bank promptly because reporting time can affect the liability assessment under applicable directions.", "Record date, amount, account alert, merchant/ATM descriptor, last four digits, and report time. Keep the complaint number and bank acknowledgement; never share OTP, PIN, CVV, or net-banking password."),
    ("Debit cards", "ATM cash not dispensed but account debited", "An ATM transaction debited the account but no cash, or only partial cash, was dispensed.", "Note the ATM location and terminal identifier if visible, date and time, amount requested, cash received, and transaction reference. Raise a failed ATM transaction complaint with the card-issuing bank using its official channel and ask for the expected resolution route and reference number. Do not revisit an unsafe ATM to seek help from strangers.", "Save the bank alert and account entry. The issuer may coordinate with the ATM operator; ask for the applicable dispute timeline and follow up with the complaint number."),
    ("Debit cards", "ATM cash retained or card captured", "An ATM retained the card or cash did not return after the transaction.", "Contact the issuing bank immediately to block the card if it is not safely returned and report the ATM incident. Record the ATM address, operator name, terminal ID, time, and whether a debit occurred. Do not disclose a PIN to a person claiming to be able to retrieve the card.", "Keep the alert, ATM receipt, and complaint ID. If the ATM is in a bank branch, notify staff while remaining in a safe public area."),
    ("Debit cards", "POS purchase declined but account debited", "A shop or online point-of-sale transaction failed, but the linked account shows a debit.", "Ask the merchant whether the transaction completed and obtain the acquirer or terminal reference if available. Contact the bank through its official channel with the failed-payment alert and request a reversal or dispute investigation. Check whether the debit is pending or posted before attempting a second payment.", "Retain receipt or order screen, bank alert, transaction reference, date, time, and amount. The merchant and issuer may see different settlement statuses."),
    ("Debit cards", "Duplicate debit-card purchase", "Two debits appear for one purchase or one transaction attempt.", "Compare both entries and merchant receipts, then ask the merchant whether a reversal was already initiated. File a duplicate transaction complaint with the bank if both debits post or the merchant cannot resolve it. Ask the bank to confirm whether each entry is pending or settled.", "Provide both transaction references, dates, amounts, merchant, and a single receipt. Follow the issuer's written process and preserve the complaint ID."),
    ("Debit cards", "Debit-card refund delayed", "A merchant says a refund was issued to the debit card, but the bank account is not credited.", "Request the refund trace or reference from the merchant and match it to the original transaction. Give those details to the bank and ask whether the refund was received, rejected, or is still processing. If the merchant cannot prove a refund, escalate with the order cancellation and payment evidence.", "Keep the original debit entry, cancellation proof, refund confirmation, trace number, and bank complaint reference. Processing timelines vary by issuer, network, and merchant."),
    ("Debit cards", "Debit card blocked or hot-listed unexpectedly", "A card is blocked after failed PIN attempts, suspected fraud, or a bank security action.", "Use the bank's official app or published service number to identify the reason and request an unblock or replacement process. Verify identity only through the bank's secure procedure. If the block followed suspicious activity, review recent account transactions and change compromised credentials from a trusted device.", "Note when the block began, any alert text, the last four digits, and support reference. Never disclose an OTP or PIN to someone who calls unexpectedly."),
    ("Debit cards", "Debit-card PIN reset or activation issue", "A new, reissued, or replacement card cannot be activated or the PIN does not work.", "Use only the issuer's official app, ATM, branch, or published PIN-generation process. Confirm the card is active and the correct card is selected; avoid repeated guesses that may block it. Contact the bank if the secure PIN flow fails and request a reference number.", "Keep the card delivery and activation notice. No bank employee needs the customer's PIN or OTP; do not send either by message or email."),
    ("Debit cards", "International or contactless debit payment issue", "An overseas, online, tap-to-pay, or contactless debit transaction is declined or unexpected.", "Review the bank's transaction controls, card usage settings, limits, and account alerts in the official app. Enable only the channel and region needed, and disable them afterward where the bank provides that control. For an unauthorized transaction, block the card and report it immediately.", "Record merchant, currency, amount, channel, and decline details. Conversion rates, cross-border fees, and limits depend on the bank's current schedule and card terms."),
    ("Debit cards", "Debit-card replacement or delivery problem", "A damaged, expired, or blocked debit card has not been replaced or was delivered to an unexpected address.", "Check the request status and registered mailing address through the bank's secure channel. Ask the bank to stop a card sent to an unknown address, block the old card if needed, and confirm delivery or branch-collection options. Request written confirmation of the replacement request.", "Keep the request ID, address update confirmation, courier tracking, and last four digits only. Never share full card details with a courier or unknown caller."),
    ("Debit cards", "Debit-card transaction limit or cash withdrawal issue", "A card transaction or ATM withdrawal is declined despite sufficient account balance.", "Check daily usage limits, available balance, account restrictions, ATM/network limits, and channel settings in the official bank app. Ask the issuer to identify the decline reason before retrying. If the account is restricted, obtain the required steps and expected review process from the bank.", "Capture date, terminal/merchant, amount, and any displayed decline code. Bank limits can change and may differ by card variant and channel."),
    ("Debit cards", "Debit-card fraud report and customer liability", "A customer needs to understand what happens after promptly reporting an unauthorized electronic transaction.", "Report the transaction immediately to the bank through a documented official channel, block the affected card, secure online-banking access, and request a complaint number. The RBI customer-protection framework distinguishes cases by whether the bank, customer, or a third party was responsible and by reporting timing; the bank should explain the applicable assessment and evidence needed.", "Record when the transaction alert arrived and when it was reported. Do not assume a refund or liability outcome before the bank reviews the facts and current directions."),
    ("Home loans", "Home-loan EMI debit failed", "A scheduled EMI was not debited, or the loan account shows overdue despite funds being available.", "Check the linked account balance and mandate status, then review the loan ledger and bank statement for a debit or reversal. Contact the lender promptly to confirm whether payment is outstanding, how to pay through an official method, and whether a fee or credit-report entry is being considered. Ask for written confirmation after payment posts.", "Save mandate status, account statement, EMI schedule, payment receipt, and lender reference. Verify the due date and bounce charge in the signed agreement and current schedule of charges."),
    ("Home loans", "Home-loan interest-rate reset or EMI increase", "A floating-rate home loan has a rate change, higher EMI, or longer remaining tenure.", "Request the reset date, benchmark, spread, old and new rates, revised amortization schedule, and available options. Compare whether the lender proposes an EMI change, tenure extension, or other permitted choice. Do not rely only on a headline benchmark; confirm the loan agreement and lender notice.", "Retain sanction letter, agreement, reset notice, prior and revised schedules, and communication. The effect depends on the contract, benchmark, reset frequency, and lender policy."),
    ("Home loans", "Home-loan part-prepayment request", "A borrower wants to use surplus funds to reduce principal and needs the impact confirmed.", "Ask the lender for the current principal, payment method, minimum amount if any, allocation date, revised EMI or tenure, and any charges applicable to the specific loan. Obtain a written simulation and confirmation that the amount was applied to principal rather than held as advance EMI. Review the RBI 2025 pre-payment directions for loans sanctioned or renewed on or after 1 January 2026 and their applicability to the borrower's lender, purpose, and rate type.", "Keep the lender quote, payment proof, loan account entry, and revised amortization schedule. The new directions generally prohibit prepayment charges on floating-rate loans to individuals for non-business purposes within scope, but older loans and exceptions require contract- and rule-specific review."),
    ("Home loans", "Home-loan foreclosure or closure charges", "A borrower is closing the loan and needs a final settlement quote or questions a charge.", "Request a dated foreclosure statement showing principal outstanding, interest through the proposed date, fees, and payment instructions. Ask the lender to identify the contractual and regulatory basis for each charge. Check the effective date and scope of the RBI 2025 pre-payment directions for loans sanctioned or renewed from 1 January 2026; do not assume the same treatment for every earlier loan or fixed-rate facility.", "Preserve the sanction letter, loan agreement, rate type, renewal history, foreclosure quote, and final payment receipt. Obtain a zero-balance confirmation and a checklist for return of original documents and lien release."),
    ("Home loans", "Home-loan disbursement delayed", "A sanctioned home loan is not disbursed, or a stage-wise construction payment is held.", "Ask the lender for the exact pending condition, approved disbursement schedule, property or builder document, inspection requirement, and responsible team. Confirm the developer's stage certificate and borrower contribution records. Escalate through the lender's grievance channel if the stated conditions are met but payment remains unexplained.", "Keep the sanction letter, conditions precedent, builder demand, receipts, inspection reports, and correspondence. Do not pay an unverified agent to accelerate disbursement."),
    ("Home loans", "Home-loan application rejected or delayed", "The application is rejected, pending, or additional documents are repeatedly requested.", "Request a status update and the specific unresolved document or verification. Review the applicant and co-applicant credit reports for errors, confirm income and property records are consistent, and ask the lender which factors can be corrected or whether a fresh application is appropriate. Approval criteria remain lender-specific.", "Keep application ID, document checklist, submission dates, and written communications. Avoid repeated applications before understanding their potential credit-enquiry impact."),
    ("Home loans", "Home-loan balance transfer or rate conversion query", "A borrower wants to compare a refinance, balance transfer, or conversion offer.", "Obtain the current principal and foreclosure statement, proposed lender's KFS and sanction terms, processing and legal costs, rate type, reset rules, and total repayment scenario. Compare the full cost over a realistic holding period, not only the advertised rate. Confirm document release and disbursement coordination before paying any transfer-related fee.", "Save both lenders' written offers, fee schedules, amortization schedules, valuation/legal requirements, and agreement clauses. A quoted rate may depend on borrower profile and property verification."),
    ("Home loans", "Home-loan account statement or interest certificate missing", "A borrower needs an annual interest certificate, repayment history, or account statement for records.", "Request the document through the lender's secure portal or branch and verify the loan account and financial year. Reconcile principal and interest figures with actual payments and the annual schedule; report discrepancies in writing. Ask for a complaint number if the document request is not acknowledged.", "Keep request date, account statement, certificate received, and correction correspondence. Tax treatment is individual and should be checked with a qualified tax professional."),
    ("Home loans", "Home-loan original property documents not returned", "The loan is closed but original property documents or a charge release confirmation are pending.", "Obtain written confirmation that the loan has a zero balance and ask for a dated document-return appointment, itemized original-document list, and charge or lien release steps. Compare the returned documents against the lender's deposit receipt and report any missing item immediately. Keep copies of all handover acknowledgements.", "Retain the closure letter, no-dues certificate, document inventory, identity-verified receipt, and registrar or society updates. If a document is missing, ask the lender for its formal remediation process."),
    ("Home loans", "Home-loan co-applicant or ownership mismatch", "Borrower, co-applicant, property ownership, or repayment details do not match across documents.", "Ask the lender which relationship, income, identity, or ownership records must be corrected and whether all co-owners must execute a document. Do not alter source records informally. Submit corrected official documents through the verified channel and request acknowledgement.", "Keep the lender checklist, consent records, property title documents, and acknowledgements. Legal ownership and tax consequences require qualified advice."),
    ("Home loans", "Home-loan credit-report account or overdue error", "A loan is marked overdue, open, or unpaid despite payments or closure.", "Obtain the credit report and identify the lender-reported account, balance, and date. Raise a written correction request with both the lender and credit information company, attach payment or closure proof, and record the complaint IDs. RBI's credit information directions provide a complaint-resolution framework, including a compensation mechanism for eligible delays beyond the prescribed 30-day period; check the current directions for coverage and process.", "Save dated report copies, dispute acknowledgement, loan ledger, payment receipts, and response. Credit-report corrections require the reporting institution to verify its records."),
    ("Home loans", "Home-loan insurance bundled with property finance", "A borrower sees a premium, policy, or insurance requirement linked to a home-loan offer.", "Ask which insurance is optional or required under the specific loan and property terms, who is the insured, the premium, coverage, exclusions, cancellation and refund conditions, and whether the loan terms change if a separate policy is chosen. Obtain the insurance document and lender requirement in writing before consenting.", "Keep proposal, consent, premium receipt, policy schedule, benefit illustration, and lender communication. Do not infer product suitability or tax treatment from a loan salesperson's verbal statement."),
    ("Home loans", "Home-loan pre-EMI or construction-stage interest confusion", "A borrower is charged pre-EMI interest or is unsure how staged disbursement affects repayments.", "Compare disbursement dates and amounts with the loan ledger and agreement. Ask the lender how interest is calculated during partial disbursement, when full EMI starts, and how each construction milestone changes the schedule. Confirm the next debit amount and date in writing.", "Retain builder demand notices, disbursement certificates, lender ledger, and repayment schedule. Charges and repayment choices depend on the contract and disbursement structure."),
    ("Personal loans", "Personal-loan EMI bounce or missed payment", "An EMI failed, was returned, or appears overdue in the lender's system.", "Check the bank statement and mandate status, then contact the lender promptly through its verified app or number. Confirm the exact overdue amount, official payment method, fees, and how to prevent a repeat failure. After paying, request a ledger update and written confirmation of the overdue status.", "Keep debit mandate status, payment proof, lender statement, and complaint reference. Do not send money to a collection agent's personal account."),
    ("Personal loans", "Personal-loan foreclosure or part-prepayment question", "A borrower wants to repay early or disputes an early closure charge.", "Request a dated closure or part-payment quote and ask how payments are allocated, what charges apply, and when the revised schedule or no-dues confirmation will issue. Review the RBI 2025 pre-payment directions: for loans sanctioned or renewed on or after 1 January 2026, the directions generally prohibit charges on floating-rate loans to individuals for non-business purposes within scope; confirm lender type, purpose, rate, and loan date.", "Keep sanction date, renewal record, loan purpose, rate type, agreement, quote, payment proof, and final ledger. Do not assume the 2026-effective framework automatically rewrites an older contract."),
    ("Personal loans", "Personal-loan KFS, APR, or fee mismatch", "The actual cost, fees, or repayment schedule differs from the offer communicated to the borrower.", "Compare the Key Facts Statement with the sanction letter, agreement, disbursement amount, EMI, annual percentage rate, processing fee, insurance, and repayment dates. Ask the lender to explain every difference in writing before accepting or continuing the loan. For eligible retail term loans, RBI's KFS framework is intended to provide standardized key loan facts and APR disclosure.", "Keep offer screens, KFS, agreement, bank credit entry, and payment schedule. Verify which charges were disclosed and whether the product and date fall within the applicable RBI circular."),
    ("Personal loans", "Personal-loan disbursal lower than sanctioned amount", "The amount credited is lower than expected after a personal loan is approved.", "Compare the sanction amount with the KFS and disbursement statement. Ask for an itemized explanation of deductions, processing fees, insurance premiums, taxes, and any other charge, including whether each was disclosed and consented to. Raise a written complaint if the calculation is inconsistent.", "Save approval message, KFS, signed agreement, bank statement, and fee schedule. Never transfer a separate 'release fee' to an unverified person."),
    ("Personal loans", "Personal-loan rejection or eligibility question", "An application is declined or the borrower wants to understand eligibility factors.", "Ask the lender what information can be shared about the decision and review income, existing obligations, employment details, identity records, and credit report for errors. Correct inaccurate credit data with the reporting lender and bureau before deciding whether to reapply. Do not pay a broker who promises approval.", "Keep the application number, requested document list, lender response, and credit-report dispute record. A lender's underwriting rules and approval decisions are institution-specific."),
    ("Personal loans", "Personal-loan credit-report error after repayment", "A closed or repaid loan still shows a balance, overdue, or active account.", "Download a current credit report and record the account details. File a dated correction dispute with the lender and credit information company with closure letter and repayment proof. Track the complaint reference and response date; RBI's credit information directions describe a 30-day resolution framework and an eligible compensation mechanism for delays, subject to the current rules.", "Save the original and updated report, no-dues certificate, payment receipts, dispute submissions, and replies. Do not file multiple conflicting disputes for the same item."),
    ("Personal loans", "Personal-loan recovery calls or harassment concern", "A borrower receives repeated or threatening collection contact or is unsure whether a caller is genuine.", "Do not share OTPs, passwords, or payment to a personal account. Verify the lender and assigned agency through the lender's published contact details; document dates, numbers, messages, and specific conduct. Contact the lender's grievance officer and request a written account statement and approved repayment channel. If there is an immediate threat, contact local authorities.", "Keep call logs, lawful recordings if applicable, messages, agent identity, and complaint numbers. Do not retaliate or post sensitive account details publicly. Ask a qualified adviser about legal options."),
    ("Personal loans", "Personal-loan settlement offer or closure wording", "A borrower receives a settlement, waiver, or closure offer and needs to understand its credit consequences.", "Request the lender's offer on official letterhead or secure account channel, including amount, due date, conditions, and exact account-reporting status. Confirm whether it is full repayment or settlement for less than the contractual balance; ask how the credit information will be furnished. Do not pay until the offer is verified with the lender.", "Keep the offer, account ledger, payment receipt, and closure or settlement letter. A settlement can affect future credit assessment; consult the lender and qualified adviser before accepting."),
    ("Personal loans", "Personal-loan payment posted late or twice", "An EMI payment was debited twice, credited late, or not matched to the loan account.", "Compare bank debit entries with the lender's loan ledger and mandate records. Contact the lender and bank with both payment references; ask which payment was received, whether a duplicate refund is due, and whether any overdue or fee entry can be corrected. Do not share full account credentials.", "Save bank statements, mandate messages, UTR/payment IDs, lender ledger, and case numbers. Continue monitoring until both the account and any credit reporting are corrected."),
    ("Personal loans", "Personal-loan top-up or refinancing proposal", "A borrower is offered a top-up or refinance and wants to compare total cost.", "Request the new KFS, APR, net disbursal, old-loan closure amount, fees, insurance, repayment schedule, and prepayment rules. Compare total remaining cost under the current loan with total cost under the new agreement. Ask whether the existing loan is closed directly and obtain written confirmation.", "Keep both agreements, KFS documents, sanction terms, and account statements. A lower EMI can result from a longer tenure and higher total interest; compare the full schedule."),
    ("Personal loans", "Digital personal-loan app or lender legitimacy concern", "A borrower is asked to install an unknown app, grant broad phone permissions, or pay an upfront fee.", "Verify the lender's legal identity and whether the app is an authorized channel using the lender's official website or published contact details. Do not share OTP, contacts access, screen sharing, or remote-control access. If a loan was opened without consent, contact the regulated lender, secure accounts, preserve evidence, and report through appropriate official channels.", "Record app name, developer, permissions, messages, URLs, lender identity, and transaction trail. Do not install unknown APKs or pay a third party to cancel a loan."),
    ("Personal loans", "Personal-loan rate, tenure, or EMI changed", "The lender changes the EMI or repayment details or the borrower cannot reconcile the schedule.", "Compare the revised schedule with the signed loan terms, benchmark or fixed-rate clause, payment history, and any restructuring or top-up agreement. Ask the lender for the calculation and effective date in writing. If the change was not agreed or disclosed, open a formal grievance and retain the complaint number.", "Save the original and revised KFS/schedules, notices, agreement, and payment entries. Do not stop repayment without a written plan from the lender or qualified adviser."),
]

assert len(TOPICS) == 50, f"Expected exactly 50 documents; found {len(TOPICS)}"

font_regular = Path("C:/Windows/Fonts/arial.ttf")
font_bold = Path("C:/Windows/Fonts/arialbd.ttf")
if font_regular.exists() and font_bold.exists():
    pdfmetrics.registerFont(TTFont("Finwell", str(font_regular)))
    pdfmetrics.registerFont(TTFont("Finwell-Bold", str(font_bold)))
    FONT, BOLD = "Finwell", "Finwell-Bold"
else:
    FONT, BOLD = "Helvetica", "Helvetica-Bold"

styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name="FinTitle", parent=styles["Title"], fontName=BOLD, fontSize=20, leading=26, textColor=colors.HexColor("#14362F"), alignment=TA_CENTER, spaceAfter=7))
styles.add(ParagraphStyle(name="FinSub", parent=styles["Normal"], fontName=FONT, fontSize=9, leading=14, textColor=colors.HexColor("#63746F"), alignment=TA_CENTER, spaceAfter=14))
styles.add(ParagraphStyle(name="FinHead", parent=styles["Heading2"], fontName=BOLD, fontSize=12, leading=16, textColor=colors.HexColor("#167966"), spaceBefore=10, spaceAfter=4, keepWithNext=True))
styles.add(ParagraphStyle(name="FinBody", parent=styles["BodyText"], fontName=FONT, fontSize=9, leading=14, textColor=colors.HexColor("#283834"), spaceAfter=6))
styles.add(ParagraphStyle(name="FinSmall", parent=styles["BodyText"], fontName=FONT, fontSize=7.4, leading=10, textColor=colors.HexColor("#65736F"), spaceAfter=3, wordWrap="CJK"))
styles.add(ParagraphStyle(name="FinMeta", parent=styles["BodyText"], fontName=FONT, fontSize=8, leading=12, textColor=colors.HexColor("#34423C"), spaceAfter=0))


def footer(canvas, doc):
    canvas.saveState()
    width, _height = A4
    canvas.setStrokeColor(colors.HexColor("#DDE6E2"))
    canvas.line(18 * mm, 15 * mm, width - 18 * mm, 15 * mm)
    canvas.setFont(FONT, 7)
    canvas.setFillColor(colors.HexColor("#7D8A86"))
    canvas.drawString(18 * mm, 10 * mm, "FINWELL  |  General customer-support reference  |  India")
    canvas.drawRightString(width - 18 * mm, 10 * mm, f"Page {doc.page}")
    canvas.restoreState()


def build_doc(index, item):
    category, title, focus, action, evidence = item
    source_id = f"FW-{index:03d}"
    filename = f"{source_id}_{re.sub(r'[^a-z0-9]+', '_', title.lower()).strip('_')}.pdf"
    is_credit = category == "Credit cards"
    is_debit = category == "Debit cards"
    is_loan = not (is_credit or is_debit)
    related = [RBI["card"]] if is_credit else [RBI["unauthorized"]] if is_debit else [RBI["kfs"], RBI["prepayment"], RBI["credit_info"]]
    related.append(RBI["ombudsman"])
    sections = [
        ("1. Issue summary", f"{focus} This reference gives a safe first-response workflow for a customer-support team. It cannot inspect an account or replace the issuer's contract, fraud investigation, or a qualified professional's advice."),
        ("2. Immediate customer actions", action),
        ("3. Evidence and information to collect", evidence),
        ("4. Support-team investigation checklist", f"Confirm the customer's identity only through the institution's approved authentication flow. Find the relevant transaction or loan ledger entry, verify the status and timestamps, review the signed terms and applicable schedule of charges, and check for prior disputes or reversals. Separate verified facts from customer recollection. Give the customer a case number, explain the next update channel, and record each handoff. Do not promise an outcome or timeline that the institution has not confirmed."),
        ("5. Complaint writing template", f"Subject: Request for review - {title}. Include the account or card reference using only the institution-approved masked identifier; date and amount; a short sequence of events; the resolution requested; supporting evidence; and the best secure contact channel. Ask for written acknowledgement and a complaint reference. Never attach an unmasked card number, PIN, CVV, OTP, password, or full identity document unless a verified institutional process specifically requires a protected document upload."),
        ("6. Escalation and regulatory context", "Start with the issuer or lender's official grievance process and keep its acknowledgement. If the issue is not resolved, review the institution's escalation officer and current RBI Integrated Ombudsman Scheme process at the official CMS. The RBI Ombudsman route generally follows an unsatisfactory or rejected response, or no response within 30 days, and is subject to the scheme's maintainability rules and exclusions. Use only official RBI and institution contact channels."),
        ("7. Customer protection and privacy", "If fraud is suspected, treat speed as important: use official channels to block or secure the relevant payment instrument, report the event, and protect account credentials. RBI's electronic transaction liability framework depends on the facts, bank/customer responsibility, and reporting circumstances. Keep the report time and the bank's acknowledgement; do not state a guaranteed refund or liability outcome."),
        ("8. Recordkeeping and follow-up", "Maintain a dated chronology of notices, customer reports, documents supplied, investigation steps, and resolution. Reconcile the final bank or lender ledger with the complaint outcome. Ask the customer to review the next statement or credit report where relevant and to contact the institution if the correction is not visible. Follow the institution's retention, privacy, and complaint-handling policies."),
    ]
    if is_loan:
        sections[5] = ("6. Loan disclosures and repayment review", "Compare the Key Facts Statement (KFS), annual percentage rate, sanction letter, agreement, disbursement, and current repayment schedule. RBI's KFS framework applies to specified retail term-loan products and is intended to show key terms and APR; verify the applicable date and lender. RBI's 2025 pre-payment directions apply to loans sanctioned or renewed from 1 January 2026; the scope depends on lender category, loan purpose, borrower, rate type, and other conditions. Check the actual contract and current RBI directions before stating whether a fee is allowed." )
    if "credit-report" in title.lower() or "credit report" in title.lower():
        sections[6] = ("7. Credit-information correction", "Raise a dated correction request with the reporting lender and credit information company. RBI's credit information directions describe a 30-calendar-day resolution framework and a compensation mechanism for eligible delay beyond that period. Eligibility, day-counting, required notice, and the responsible entity depend on the current directions; verify them before quoting compensation or an outcome.")

    story = [Spacer(1, 8), Paragraph(escape(title), styles["FinTitle"]), Paragraph(f"REFERENCE {source_id} &nbsp; | &nbsp; {escape(category)} &nbsp; | &nbsp; India edition: 25 November 2026", styles["FinSub"])]
    meta = Table([[Paragraph("Customer issue", styles["FinMeta"]), Paragraph(escape(focus), styles["FinMeta"])], [Paragraph("Reference type", styles["FinMeta"]), Paragraph("General workflow; confirm the institution's current terms", styles["FinMeta"])]], colWidths=[32 * mm, 142 * mm])
    meta.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (0, -1), colors.HexColor("#EEF5F2")), ("TEXTCOLOR", (0, 0), (0, -1), colors.HexColor("#167966")),
        ("FONTNAME", (0, 0), (0, -1), BOLD), ("FONTNAME", (1, 0), (1, -1), FONT), ("FONTSIZE", (0, 0), (-1, -1), 8),
        ("LEADING", (0, 0), (-1, -1), 12), ("VALIGN", (0, 0), (-1, -1), "TOP"), ("GRID", (0, 0), (-1, -1), .4, colors.HexColor("#DDE6E2")),
        ("LEFTPADDING", (0, 0), (-1, -1), 7), ("RIGHTPADDING", (0, 0), (-1, -1), 7), ("TOPPADDING", (0, 0), (-1, -1), 6), ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
    ]))
    story += [meta, Spacer(1, 8)]
    for heading, content in sections:
        story += [Paragraph(escape(heading), styles["FinHead"]), Paragraph(escape(content), styles["FinBody"])]
    story += [Paragraph("Official reference links", styles["FinHead"])]
    for label, url in related:
        story.append(Paragraph(f"{escape(label)}<br/><font color='#167966'>{escape(url)}</font>", styles["FinSmall"]))
    story += [Spacer(1, 7), Paragraph("Important: General educational material only. No bank-specific terms, account access, legal determination, credit decision, or financial recommendation is provided. Rules and product terms can change; confirm them with the regulated institution and official current sources.", styles["FinSmall"])]
    path = OUT / filename
    doc = SimpleDocTemplate(str(path), pagesize=A4, rightMargin=18 * mm, leftMargin=18 * mm, topMargin=17 * mm, bottomMargin=21 * mm, title=title, author="Finwell Customer Support Knowledge Base", subject=category)
    doc.build(story, onFirstPage=footer, onLaterPages=footer)
    return {"id": source_id, "filename": filename, "title": title, "topic": category, "focus": focus, "sources": [{"title": label, "url": url} for label, url in related]}


manifest = {"name": "Finwell Indian cards and loans support knowledge base", "edition": "2026-11-25", "documents": [build_doc(i, item) for i, item in enumerate(TOPICS, start=1)]}
(ROOT / "knowledge_base" / "manifest.json").write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")
public_pdfs = ROOT / "public" / "knowledge_base" / "pdfs"
public_pdfs.mkdir(parents=True, exist_ok=True)
for item in manifest["documents"]:
    shutil.copy2(OUT / item["filename"], public_pdfs / item["filename"])
print(f"Generated {len(manifest['documents'])} PDFs at {OUT}")
